const iconPaths={home:'<path d="m3 10 9-7 9 7v10H7V10m5 10v-7h5v7"/>',course:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',review:'<path d="M3 11a9 9 0 1 1 3 8M3 4v7h7m2-4v6l4 2"/>',saved:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',foundation:'<path d="M4 20V4h6v16M14 20V9h6v11M2 20h20"/>',question:'<path d="M8 8a4 4 0 1 1 6 3.5c-2 1-2 2.5-2 3.5"/><circle cx="12" cy="19" r=".8"/>',time:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H8l-5 3V7a5 5 0 0 1 5-5h8a5 5 0 0 1 5 5v4Z"/><path d="M7 8h10M7 12h6"/>',link:'<path d="m9 15 6-6m-7 9-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2-3 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z"/>',check:'<path d="m5 12 4 4L19 6"/>',words:'<path d="M3 5h7a3 3 0 0 1 3 3v13a5 5 0 0 0-5-2H3V5Zm18 0h-5a3 3 0 0 0-3 3v13a5 5 0 0 1 5-2h3V5Z"/>',audio:'<path d="m11 4-6 5H2v6h3l6 5V4Zm4 4q6 4 0 8m3-11q9 7 0 14"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'};
function icon(name){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.course}</svg>`}
const $=s=>document.querySelector(s),KEY='thai-steps-v1';
const fresh=()=>({done:[],saved:[],wrong:[],passed:[],speed:0.85,voice:'',hideTranslation:false});
let state=fresh(),storageOK=true;try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch(e){storageOK=false}
let view=location.hash==='#words'?'words':'home',current=1,moduleFilter='all',search='',quiz=null,voices=[],toastTimer;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){storageOK=false;toast('学習記録を保存できません。設定からデータを書き出してください。')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function count(m){return lessons.filter(l=>l.m===m&&state.done.includes(l.id)).length}
function nextLesson(){return orderedLessons.find(l=>!state.done.includes(l.id))||lessons[0]}
function speaker(id,i){return `<div><button class="speak" aria-label="例文${i+1}をタイ語で再生" onclick="speak(${id},${i})"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M11 4 5 9H2v6h3l6 5V4Z"/><path d="M15 8q6 4 0 8m3-11q9 7 0 14"/></svg>音声</button><button class="slow" onclick="speak(${id},${i},true)" aria-label="例文${i+1}をゆっくり再生">ゆっくり</button></div>`}
function loadVoices(){if('speechSynthesis'in window)voices=speechSynthesis.getVoices()}
loadVoices();if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',()=>{loadVoices();if(view==='settings')render()});
function speakThaiText(text,slow=false){if(!('speechSynthesis'in window)){toast('このブラウザは音声再生に対応していません。ChromeやSafariで開いてください。');return}loadVoices();speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='th-TH';const v=voices.find(v=>v.voiceURI===state.voice&&/^th/i.test(v.lang))||voices.find(v=>/^th/i.test(v.lang));if(v)u.voice=v;u.rate=slow?0.65:Number(state.speed);u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('音声を再生できませんでした。端末のタイ語音声・通信状態を確認してください。')};speechSynthesis.speak(u);if(!v)toast('端末にタイ語音声を要求しました。聞こえない場合は「音声設定」を確認してください。')}
function speak(id,i,slow=false){speakThaiText(lessons.find(l=>l.id===id).examples[i].th,slow)}

function go(v){view=v;quiz=null;if(v!=='words'){wordCurrent=null;wordSession=null}render();window.scrollTo(0,0)}
function openLesson(id){current=id;view='lesson';quiz=null;render();window.scrollTo(0,0)}
function moveLesson(delta){const i=orderedLessons.findIndex(l=>l.id===current);if(orderedLessons[i+delta])openLesson(orderedLessons[i+delta].id)}
function openModule(m){moduleFilter=String(m);search='';go('course')}
function toggleSaved(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();render()}
function markDone(){if(!state.done.includes(current)){state.done.push(current);save();toast('学習済みにしました。確認問題にも挑戦してみよう。')}render()}
function nav(){const items=[['home','ホーム'],['words','単語'],['course','文法'],['review','文法復習'],['saved','文法保存']];$('#nav').innerHTML=items.map(([v,t])=>`<button class="navbtn ${view===v||(view==='lesson'&&v==='course')?'active':''}" onclick="go('${v}')" aria-label="${t}">${icon(v)}<span>${t}</span>${v==='review'&&state.wrong.length?`<span class="count">${state.wrong.length}</span>`:''}</button>`).join('')}
function moduleCard(m,i){const n=count(i),total=chapterLessons(i).length;return `<button class="x-chapter" onclick="openModule(${i})"><span class="x-chapter-icon">${icon(['foundation','question','time','chat','link','spark'][i])}</span><span class="x-chapter-body"><b>${i+1}. ${m.name}<small>${m.level}</small></b><span>${m.desc}</span></span><span class="x-chapter-progress">${n} / ${total}</span><span class="track"><span style="width:${n/total*100}%"></span></span></button>`}
function searchWordsFromHome(q){wordQuery=String(q||'').trim();wordCurrent=null;wordSession=null;wordScope='all';wordPage=0;go('words');const el=document.getElementById('word-search');if(el&&wordQuery)el.focus()}
function home(){const l=nextLesson(),allDone=state.done.length===lessons.length,records=Object.values(wordState.records),seen=records.filter(r=>r.seen>0).length,due=records.filter(r=>r.manual||(r.seen>0&&r.due<=Date.now())).length,favorites=records.filter(r=>r.favorite).length,total=typeof WORD_LIBRARY==='undefined'?'5,077':WORD_LIBRARY.unique.toLocaleString(),title=l.title.replace(/[\u0E00-\u0E7F]+/g,'').replace(/\s+/g,' ').trim();return `<section class="x-dict x-dict-home" aria-label="辞書"><label class="x-dict-label" for="home-search">辞書</label><form class="x-search" role="search" onsubmit="event.preventDefault();searchWordsFromHome(this.q.value)"><span class="x-search-icon" aria-hidden="true">${searchIcon()}</span><input id="home-search" name="q" type="search" enterkeyhint="search" autocomplete="off" placeholder="日本語・タイ語・読みで検索" title="日本語・タイ語・声調付き/なしローマ字・カタカナ発音で検索できます"><button class="btn" type="submit">検索</button></form></section><section class="x-home" aria-label="学習を始める"><article class="x-card"><div class="x-card-head"><h2>${icon('words')} 単語</h2><span>登録 ${total}語</span></div><div class="x-stats" aria-label="単語の学習状況"><div><strong>${seen.toLocaleString()}</strong><span>学習した語</span></div><div><strong>${due.toLocaleString()}</strong><span>復習する語</span></div><div><strong>${favorites.toLocaleString()}</strong><span>お気に入り</span></div></div><div class="x-card-actions"><button class="btn" onclick="wordCurrent=null;wordSession=null;go('words')">単語帳を開く ${icon('arrow')}</button>${due?`<button class="btn light" onclick="wordCurrent=null;wordSession=null;wordScope='review';go('words')">復習する</button>`:''}</div></article><article class="x-card"><div class="x-card-head"><h2>${icon('course')} 文法</h2><span>${state.done.length} / ${lessons.length} 学習済み</span></div><p class="x-next">${allDone?'全レッスンを学習済み':`次のレッスン ${displayNumber(l.id)} · ${esc(modules[l.m].name)}`}</p><h3 class="x-lesson">${allDone?'学んだ文法を、もう一度。':esc(title)}</h3><div class="track"><div style="width:${state.done.length/lessons.length*100}%"></div></div><div class="x-card-actions"><button class="btn" onclick="${allDone?"go('review')":`openLesson(${l.id})`}">${allDone?'復習する':state.done.length?'続きから学ぶ':'文法をはじめる'} ${icon('arrow')}</button><button class="btn light" onclick="go('review')">復習 <b>${state.wrong.length}</b></button><button class="btn light" onclick="go('saved')">保存 <b>${state.saved.length}</b></button></div></article></section><div class="x-section-head"><h2>文法の章</h2><button class="textbtn" onclick="moduleFilter='all';go('course')">全${lessons.length}課を見る ${icon('arrow')}</button></div><section class="x-chapters">${modules.map(moduleCard).join('')}</section>`}

function lessonRow(l){return `<button class="lessonrow" onclick="openLesson(${l.id})"><span class="num">${state.done.includes(l.id)?icon('check'):displayNumber(l.id)}</span><span class="row-content"><span class="list-tag">CHAPTER 0${l.m+1} · ${modules[l.m].level}</span><h3>${l.title}</h3><span class="list-formula">${esc(patternFor(l))}</span></span><span class="row-end">${state.saved.includes(l.id)?icon('saved'):''}${state.passed.includes(l.id)?'<span class="passed-label">正解済み</span>':''}${icon('arrow')}</span></button>`}
function filtered(){return orderedLessons.filter(l=>(moduleFilter==='all'||l.m===Number(moduleFilter))&&[l.title,l.intro,l.pattern,patternFor(l),romanizeThai((l.title.match(/[\u0e00-\u0e7f]+/g)||[]).join(' ')),...l.examples.flatMap(e=>[e.th,e.ro,e.ja])].join(' ').toLowerCase().includes(search.toLowerCase()))}
function courseList(){let ls=filtered();return ls.length?ls.map(lessonRow).join(''):'<div class="empty">該当する文法がありません。検索語を変えてみてください。</div>'}
function course(){return `<div class="eyebrow">YOUR LEARNING PATH</div><h1>カリキュラム</h1><p class="subtext">上から順に進んでも、今使いたい文法からでも。すべての課を自由に学べます。</p><div class="filterbar"><input class="field" id="search" type="search" value="${esc(search)}" placeholder="日本語・ローマ字・タイ語で検索" aria-label="レッスンを検索" oninput="search=this.value;refreshCourseList()"><select class="field" aria-label="ステップで絞り込む" onchange="moduleFilter=this.value;refreshCourseList()"><option value="all">すべてのステップ</option>${modules.map((m,i)=>`<option value="${i}" ${String(i)===moduleFilter?'selected':''}>0${i+1} ${m.name}（${m.level}）</option>`).join('')}</select></div><div id="lesson-list">${courseList()}</div>`}
function lesson(){const l=lessons[current-1],m=modules[l.m];return `<button class="textbtn back" onclick="openModule(${l.m})">← ${m.name} に戻る</button><div class="lesson-layout"><article><div class="lessonhead"><div class="eyebrow">STEP 0${l.m+1} · LESSON ${displayNumber(l.id)} / ${lessons.length} · ${m.level}</div><button class="textbtn" onclick="toggleSaved(${l.id})">${state.saved.includes(l.id)?'✓ 保存済み':'＋ この文法を保存'}</button></div><h1 class="lesson-title">${l.title}</h1>${syntaxPanel(l)}<section class="panel"><div class="panel-kicker">01 / 理解する</div><h2>しくみをつかむ</h2><p class="intro">${l.intro}</p><ul class="points">${l.points.map(p=>`<li>${p}</li>`).join('')}</ul>${l.extra?`<div class="deeper-grammar"><h3>もう一歩、使い分ける</h3>${l.extra.map(p=>`<p>${p}</p>`).join('')}</div>`:''}</section><section class="panel"><div class="section-head"><div><div class="panel-kicker">02 / 聞いて使う</div><h2>会話で使ってみる</h2></div><button class="textbtn" onclick="state.hideTranslation=!state.hideTranslation;save();render()">${state.hideTranslation?'日本語を表示':'日本語を隠す'}</button></div>${l.examples.map((e,i)=>`<div class="example"><div class="example-number">例文 ${i+1} / ${l.examples.length}</div><div class="example-line"><div class="example-text"><div class="th" lang="th">${e.th}</div><div class="ro">${e.ro}</div></div>${speaker(l.id,i)}</div>${state.hideTranslation?'':`<div class="translation">${e.ja}</div><p class="example-note">${e.note}</p>`}${wordPanel(l,i)}</div>`).join('')}</section><section class="panel"><div class="panel-kicker">03 / 確かめる</div><h2>使い方を確かめよう</h2><p class="subtext">短い1問で確認。間違えた問題は「復習」に残ります。</p><div class="settings-row"><button class="btn" onclick="startQuiz([${l.id}], 'lesson')">確認問題を解く →</button><button class="btn light" onclick="markDone()">${state.done.includes(l.id)?'✓ 学習済み':'読んだので学習済みにする'}</button></div></section><div class="bottom-actions"><button class="btn light" ${orderedLessons[0].id===l.id?'disabled':''} onclick="moveLesson(-1)">← 前のレッスン</button><button class="btn light" ${orderedLessons[orderedLessons.length-1].id===l.id?'disabled':''} onclick="moveLesson(1)">次のレッスン →</button></div></article><aside class="lesson-aside"><div class="panel"><div class="eyebrow">STEP 0${l.m+1}</div><h3>${m.name}</h3>${chapterLessons(l.m).map(x=>`<button class="mini-lesson ${x.id===l.id?'current':''}" onclick="openLesson(${x.id})"><span>${state.done.includes(x.id)?'✓':'○'}</span><span class="mini-title-content">${x.title}</span></button>`).join('')}</div><div class="note-box">音声を聞く → 文の形を見る → 自分のことに置き換えて言う。<br><br>声調付きローマ字は読みの補助です。音とセットで覚えましょう。</div></aside></div>`}
function review(){return `<div class="eyebrow">PRACTICE MAKES IT NATURAL</div><h1>復習する</h1><p class="subtext">間違いは、次に使える表現のヒント。繰り返して定着させよう。</p><div class="panel review-entry"><div><h2>もう一度解く</h2><p class="subtext" style="margin:0">間違えた問題が ${state.wrong.length} 問あります。正解すると復習リストから外れます。</p></div><button class="btn" ${state.wrong.length?'':'disabled'} onclick="startQuiz([...state.wrong],'review')">復習スタート ↻</button></div><div class="panel review-entry"><div><h2>全${lessons.length}課のまとめテスト</h2><p class="subtext" style="margin:0">${lessons.length}問をランダムな順番で出題。途中でやめても解答済みの記録は残ります。</p></div><button class="btn light" onclick="startQuiz(shuffle(orderedLessons.map(l=>l.id)),'review')">まとめて挑戦 →</button></div><div class="section-head"><h2>復習リスト</h2></div>${state.wrong.length?state.wrong.map(id=>lessonRow(lessons[id-1])).join(''):'<div class="empty"><h3>復習する問題はまだありません</h3><p class="subtext">各レッスンの確認問題に挑戦してみましょう。</p><button class="btn light" onclick="go(\'course\')">カリキュラムへ →</button></div>'}`}
function saved(){return `<div class="eyebrow">YOUR PERSONAL PHRASE SHELF</div><h1>保存した文法</h1><p class="subtext">すぐ使いたい表現を、ここにまとめておこう。</p>${state.saved.length?state.saved.map(id=>lessonRow(lessons[id-1])).join(''):'<div class="empty"><h3>気になる文法を保存しよう</h3><p class="subtext">レッスン右上の「この文法を保存」から追加できます。</p><button class="btn light" onclick="go(\'course\')">レッスンを探す →</button></div>'}`}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function startQuiz(ids,origin){quiz={ids:[...ids],i:0,results:[],choice:null,order:shuffle([0,1,2]),origin};view='quiz';render();window.scrollTo(0,0)}
function answer(n){if(quiz.choice!==null)return;quiz.choice=n;const id=quiz.ids[quiz.i],l=lessons[id-1],ok=n===l.answer;quiz.results.push(ok);if(ok){if(!state.passed.includes(id))state.passed.push(id);if(!state.done.includes(id))state.done.push(id);state.wrong=state.wrong.filter(x=>x!==id)}else{if(!state.wrong.includes(id))state.wrong.push(id);state.passed=state.passed.filter(x=>x!==id)}save();render()}
function nextQuestion(){quiz.i++;quiz.choice=null;quiz.order=shuffle([0,1,2]);render();window.scrollTo(0,0)}
function quizView(){if(quiz.i>=quiz.ids.length){const yes=quiz.results.filter(Boolean).length;return `<div class="quiz-wrap"><div class="empty"><div class="eyebrow">PRACTICE COMPLETE</div><h1>${yes} / ${quiz.ids.length} 問 正解</h1><p class="subtext">${yes===quiz.ids.length?'よくできました。例文を声に出して、会話につなげよう。':'間違えた問題を復習リストに保存しました。解説と例文を確認して、もう一度。'}</p><div class="settings-row" style="justify-content:center"><button class="btn" onclick="startQuiz([...quiz.ids],quiz.origin)">もう一度解く</button><button class="btn light" onclick="${quiz.origin==='lesson'?`openLesson(${quiz.ids[0]})`:"go('review')"}">戻る</button></div></div></div>`}const l=lessons[quiz.ids[quiz.i]-1],answered=quiz.choice!==null,ok=quiz.choice===l.answer;return `<div class="quiz-wrap"><button class="textbtn back" onclick="${quiz.origin==='lesson'?`openLesson(${l.id})`:"go('review')"}">← 問題を終了する</button><div class="quiz-top"><span class="subtext">${quiz.i+1} / ${quiz.ids.length} 問</span><div class="track"><div style="width:${quiz.i/quiz.ids.length*100}%"></div></div></div><section class="panel"><div class="eyebrow">LESSON ${displayNumber(l.id)} · ${modules[l.m].name}</div><h2>${l.q}</h2>${quiz.order.map(n=>`<button class="option ${answered&&n===l.answer?'correct':''} ${answered&&n===quiz.choice&&!ok?'wrong':''}" ${answered?'disabled':''} onclick="answer(${n})">${answered&&n===l.answer?'✓ ':''}${esc(l.options[n])}</button>`).join('')}${answered?`<div class="feedback ${ok?'':'bad'}" role="status"><strong>${ok?'正解！':'もう一度、形を確かめよう。'}</strong><br>${l.why}</div><div class="bottom-actions"><button class="textbtn" onclick="openLesson(${l.id})">文法の解説に戻る</button><button class="btn" onclick="nextQuestion()">${quiz.i===quiz.ids.length-1?'結果を見る':'次の問題'} →</button></div>`:''}</section></div>`}
function settings(){const vs=voices.filter(v=>/^th/i.test(v.lang));return `<div class="eyebrow">MAKE IT YOURS</div><h1>音声・学習データ</h1><section class="panel"><h2>タイ語の音声</h2><p class="subtext">端末・ブラウザのタイ語読み上げを使用します。再生音は端末の音声エンジンにより異なります。</p><label class="settings-label" for="voice">音声を選ぶ</label><select class="field" id="voice" onchange="state.voice=this.value;save()"><option value="">自動選択（タイ語）</option>${vs.map(v=>`<option value="${esc(v.voiceURI)}" ${v.voiceURI===state.voice?'selected':''}>${esc(v.name)}</option>`).join('')}</select><p class="subtext">${vs.length?`タイ語の音声が ${vs.length} 件あります。`:'タイ語音声が一覧にありません。再生できない場合は、端末の読み上げ設定でタイ語の音声を追加し、Chromeなどで開き直してください。'}</p><label class="settings-label" for="speed">通常再生の速さ</label><select class="field" id="speed" onchange="state.speed=Number(this.value);save()">${[[.75,'ゆっくり（0.75）'],[.85,'少しゆっくり（0.85）'],[1,'標準（1.0）']].map(([v,t])=>`<option value="${v}" ${Number(state.speed)===v?'selected':''}>${t}</option>`).join('')}</select><div style="margin-top:18px"><button class="btn light" onclick="speak(13,1)">音声を試す：ถึงแล้วนะ</button><button class="textbtn" style="margin-left:15px" onclick="if('speechSynthesis'in window)speechSynthesis.cancel()">再生を止める</button></div></section><section class="panel"><h2>声調付きローマ字について</h2><p class="subtext">本アプリは声調を「無印＝中平・à＝低・â＝下降・á＝高・ǎ＝上昇」で表記します。母音の重複は長母音、ʉ・ə・ɛ・ɔ はタイ語の母音を区別する記号です。ローマ字は発音の目安として使い、音声も一緒に確認してください。</p></section><section class="panel"><h2>学習記録のバックアップ</h2><p class="subtext">文法の進捗と、単語の学習・お気に入り・復習日は、このブラウザに記録されます。他の端末に移す場合は書き出して読み込んでください。${storageOK?'':' 現在、ブラウザの保存が利用できません。'}</p><div class="settings-row"><button class="btn light" onclick="exportData()">データを書き出す ↓</button><label class="btn light" for="import">データを読み込む ↑</label><input hidden type="file" id="import" accept="application/json,.json" onchange="importData(this.files[0])"></div><p class="subtext" style="margin:18px 0 0">読み込みは現在の記録を置き換えます。</p><button class="textbtn danger" style="margin-top:20px" onclick="resetData()">文法の学習記録をリセット</button><button class="textbtn danger" style="margin-left:18px" onclick="resetWordData()">単語の学習記録をリセット</button></section>`}
function exportData(){const b=new Blob([JSON.stringify({app:KEY,version:1,state,words:wordState},null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='thai-steps-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('バックアップを書き出しました。')}
async function importData(file){if(!file)return;try{const d=JSON.parse(await file.text());if(d.app!==KEY||d.version!==1||!d.state||!['done','saved','wrong','passed'].every(k=>Array.isArray(d.state[k])&&d.state[k].every(x=>Number.isInteger(x)&&x>=1&&x<=lessons.length)))throw Error();if(!confirm('現在の学習記録を、選んだバックアップに置き換えますか？'))return;const n=fresh();for(const k of ['done','saved','wrong','passed'])n[k]=[...new Set(d.state[k])];if([.75,.85,1].includes(d.state.speed))n.speed=d.state.speed;n.voice=typeof d.state.voice==='string'?d.state.voice:'';n.hideTranslation=!!d.state.hideTranslation;state=n;if(d.words&&typeof d.words.records==='object'&&!Array.isArray(d.words.records)){wordState=sanitizeWordState(d.words);saveWords()}save();render();toast('学習記録を読み込みました。')}catch(e){toast('Thai Steps の有効なバックアップファイルを選んでください。')}}
function resetData(){if(!confirm('学習済み・確認問題・復習リスト・保存した文法をすべて消去します。よろしいですか？'))return;state=fresh();save();render();toast('学習記録をリセットしました。')}
function render(){nav();$('#crumb').textContent=({words:'単語学習',home:'学習ホーム',course:'カリキュラム',lesson:`カリキュラム / ${modules[lessons[current-1].m].name}`,review:'復習',saved:'保存した文法',quiz:'確認問題',settings:'音声・学習データ'})[view];$('#main').innerHTML=({words:wordsView,home,course,lesson,review,saved,quiz:quizView,settings})[view]();if(view!=='words')annotateReadings($('#main'));document.title=`Thai Steps | ${$('#crumb').textContent}`}
function refreshCourseList(){document.querySelector('#lesson-list').innerHTML=courseList();annotateReadings(document.querySelector('#lesson-list'))}
window.addEventListener('hashchange',()=>{if(location.hash==='#home')go('home');else if(location.hash==='#words')go('words')});render();
